DROP SEQUENCE IF EXISTS TRIALS.SEQ_TIPO_ACUERDO_ID;
CREATE SEQUENCE IF NOT EXISTS TRIALS.SEQ_TIPO_ACUERDO_ID START WITH 100;
ALTER SEQUENCE TRIALS.SEQ_TIPO_ACUERDO_ID INCREMENT BY 1;


DROP TABLE IF EXISTS TRIALS.TBL_TIPO_ACUERDO;
CREATE TABLE TRIALS.TBL_TIPO_ACUERDO
(
   PN_ID                INT          NOT NULL PRIMARY KEY,
   S_NOMBRE             VARCHAR(80),
   FN_MATERIA           INT          NOT NULL REFERENCES TRIALS.TBL_MATERIAS (PN_ID),
   FN_TIPO_SISTEMA      INT          NULL REFERENCES TRIALS.TBL_TIPO_SISTEMA (PN_ID)
);
CREATE INDEX IF NOT EXISTS IDX_TIPO_SISTEMA ON TRIALS.TBL_TIPO_ACUERDO (FN_TIPO_SISTEMA);
CREATE INDEX IF NOT EXISTS IDX_MATERIA ON TRIALS.TBL_TIPO_ACUERDO (FN_MATERIA);

